import re


def _parse_records(text: str):
    records = []
    record = []
    field = []
    in_quotes = False
    record_started = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if in_quotes:
            if ch == "\\" and i + 1 < n and text[i + 1] == '"':
                field.append('"')
                record_started = True
                i += 2
                continue

            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    record_started = True
                    i += 2
                    continue

                j = i + 1
                while j < n and text[j] in " \t":
                    j += 1

                if j >= n or text[j] in ",\r\n":
                    in_quotes = False
                    i = j
                    continue

                field.append('"')
                record_started = True
                i += 1
                continue

            if ch == "\r":
                if i + 1 < n and text[i + 1] == "\n":
                    i += 1
                field.append("\n")
            else:
                field.append(ch)

            record_started = True
            i += 1
            continue

        if ch == '"' and (not field or all(c in " \t" for c in field)):
            in_quotes = True
            record_started = True
            i += 1
            continue

        if ch == ",":
            record.append("".join(field))
            field = []
            record_started = True
            i += 1
            continue

        if ch == "\r" or ch == "\n":
            if ch == "\r" and i + 1 < n and text[i + 1] == "\n":
                i += 1
            record.append("".join(field))
            records.append(record)
            record = []
            field = []
            record_started = False
            i += 1
            continue

        field.append(ch)
        record_started = True
        i += 1

    if record_started or record or field:
        record.append("".join(field))
        records.append(record)

    return records


def _is_data_like(value: str) -> bool:
    value = value.strip()
    if not value:
        return False
    if re.fullmatch(r"[\$€£¥]?\s*[+-]?(?:\d+(?:[.,]\d+)*|\.\d+)%?", value):
        return True
    if re.fullmatch(r"\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}", value):
        return True
    if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?(?:\s*[AaPp][Mm])?", value):
        return True
    if re.match(r"(?i)^(?:https?|ftp)://", value):
        return True
    if re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", value):
        return True
    return False


def _header_quality(record):
    score = 0.0
    seen = set()

    for value in record:
        stripped = value.strip()
        if not stripped:
            score -= 1.0
            continue

        lowered = stripped.lower()
        if lowered in seen:
            score -= 0.5
        seen.add(lowered)

        if _is_data_like(stripped):
            score -= 3.0
        else:
            score += 1.0

        if re.search(r"[A-Za-z]", stripped):
            score += 1.0
        if len(stripped) <= 80 and "\n" not in stripped:
            score += 0.5
        if re.fullmatch(r"[\w ()/.'+\-]+", stripped, re.UNICODE):
            score += 0.5

    return score


def _find_header(records, expected_width):
    candidates = [i for i, row in enumerate(records) if len(row) == expected_width]
    if not candidates:
        for i, row in enumerate(records):
            if any(value.strip() for value in row):
                return i
        return None

    best_index = candidates[0]
    best_score = float("-inf")

    for index in candidates:
        following = records[index + 1:index + 13]
        matching = sum(1 for row in following if len(row) == expected_width)
        score = _header_quality(records[index]) + matching * 3.0

        next_full = next(
            (row for row in records[index + 1:] if len(row) == expected_width),
            None
        )
        if next_full is not None:
            current_data = sum(_is_data_like(value) for value in records[index])
            next_data = sum(_is_data_like(value) for value in next_full)
            score += max(-3, min(5, next_data - current_data)) * 1.5

        if score > best_score:
            best_score = score
            best_index = index

    return best_index


def _normalize_row(row, width):
    values = [str(value) for value in row]

    if len(values) < width:
        values.extend([""] * (width - len(values)))
    elif len(values) > width:
        values = values[:width - 1] + [",".join(values[width - 1:])]

    return values


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = _parse_records(raw_csv)
    expected_width = 9
    header_index = _find_header(records, expected_width)

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = _normalize_row(records[header_index], expected_width)
    rows = [
        _normalize_row(record, expected_width)
        for record in records[header_index + 1:]
    ]

    return {"columns": columns, "rows": rows}
